stock2=stock
future_lost=0
first_stockout=-1
for e in sorted(future,key=lambda x:(x["event_time"],x["event_id"])):
    if e["kind"]=="receipt":
        stock2 += e["quantity"]
    else:
        u=min(stock2,e["quantity"])
        if e["quantity"]-u>0 and first_stockout==-1:
            first_stockout=e["event_time"]
        stock2 -= u
        future_lost += e["quantity"]-u
